  B("arts", "a_instruments", "Les instruments de musique", "Familles d'instruments, notes et orchestre", [0, 5], [
    ["Avec quoi joue-t-on du violon ?", "Avec un archet", ["Avec des baguettes", "En soufflant dedans", "Avec un petit marteau"], "L'archet est une baguette tendue de crins de cheval que l'on frotte sur les cordes."],
    ["À quelle famille appartient la flûte ?", "Les instruments à vent", ["Les instruments à cordes", "Les percussions", "Les claviers"], "On produit le son en soufflant : c'est l'air qui vibre."],
    ["À quelle famille appartient le tambour ?", "Les percussions", ["Les instruments à vent", "Les instruments à cordes", "Les cuivres"], "On frappe la peau tendue du tambour avec les mains ou des baguettes."],
    ["À quelle famille appartient la guitare ?", "Les instruments à cordes", ["Les instruments à vent", "Les percussions", "Les cuivres"], "On pince ou on gratte les cordes de la guitare pour les faire vibrer."],
    ["Quel instrument possède des touches noires et blanches ?", "Le piano", ["La trompette", "Le violon", "La batterie"], "Un piano classique a 88 touches ; en appuyant, de petits marteaux frappent des cordes."],
    ["Quel est le plus grand instrument de la famille du violon ?", "La contrebasse", ["Le violon", "L'alto", "Le violoncelle"], "Elle est si grande qu'on en joue debout ou assis sur un haut tabouret ; c'est aussi la plus grave."],
    ["Lequel de ces instruments est un cuivre ?", "La trompette", ["La clarinette", "Le hautbois", "La flûte traversière"], "Dans les cuivres, ce sont les lèvres du musicien qui vibrent contre l'embouchure."],
    ["Bien qu'il soit en métal, à quelle famille appartient le saxophone ?", "Les bois", ["Les cuivres", "Les cordes", "Les percussions"], "Le son est produit par une anche, une fine lamelle de roseau, comme pour la clarinette."],
    ["Avec quoi le chef d'orchestre dirige-t-il souvent les musiciens ?", "Une baguette", ["Un archet", "Un micro", "Un sifflet"], "Ses gestes indiquent le tempo, les nuances et le départ de chaque instrument."],
    ["Combien de cordes possède habituellement une guitare classique ?", "6", ["4", "3", "8"], "La basse électrique, elle, en a souvent 4."],
    ["Combien de cordes possède un violon ?", "4", ["6", "3", "8"], "De la plus grave à la plus aiguë : sol, ré, la, mi."],
    ["Quel instrument à cordes pincées a un grand cadre triangulaire ?", "La harpe", ["Le violoncelle", "Le piano", "Le banjo"], "Une harpe de concert compte 47 cordes et des pédales pour changer les notes."],
    ["Quel grand instrument à clavier, avec des tuyaux, trouve-t-on dans les églises ?", "L'orgue", ["Le piano", "L'accordéon", "Le xylophone"], "L'air soufflé dans des centaines de tuyaux produit le son ; certains orgues ont plusieurs claviers."],
    ["Quel instrument possède un soufflet que l'on ouvre et que l'on ferme ?", "L'accordéon", ["L'orgue", "La trompette", "L'harmonica"], "En tirant et poussant le soufflet, on fait passer l'air à travers des anches métalliques."],
    ["Quel instrument a des lames de bois que l'on frappe avec des baguettes ?", "Le xylophone", ["La guitare", "La flûte", "Le violon"], "« Xylo » veut dire « bois » en grec ; chaque lame donne une note différente."],
    ["Comment appelle-t-on un ensemble de quatre musiciens ?", "Un quatuor", ["Un trio", "Un duo", "Un quintette"], "Le quatuor à cordes réunit deux violons, un alto et un violoncelle."],
    ["Combien de notes différentes y a-t-il dans la gamme do, ré, mi, fa, sol, la, si ?", "7", ["5", "8", "12"], "Après le si, on retrouve le do, plus aigu : c'est l'octave."],
    ["Quelle note vient juste après « sol » dans la gamme ?", "La", ["Fa", "Si", "Do"], "Do, ré, mi, fa, sol, la, si, do."],
    ["Quel tambour d'Afrique de l'Ouest, en bois et en peau, se joue à mains nues ?", "Le djembé", ["Le banjo", "La cithare", "Le basson"], "Il est originaire de la région du Mali et de la Guinée ; on le frappe au centre ou sur le bord."],
  ]);

  B("arts", "a_compositeurs", "Compositeurs célèbres", "Du baroque au XXe siècle", [3, 11], [
    ["Quel compositeur autrichien, enfant prodige, a écrit La Flûte enchantée ?", "Mozart", ["Beethoven", "Bach", "Vivaldi"], "Wolfgang Amadeus Mozart jouait en concert devant les cours d'Europe dès l'âge de six ans."],
    ["Quel compositeur allemand a continué à composer alors qu'il était devenu sourd ?", "Beethoven", ["Mozart", "Chopin", "Haydn"], "Il a composé sa 9e symphonie alors qu'il n'entendait presque plus rien."],
    ["Quel compositeur italien a écrit Les Quatre Saisons ?", "Vivaldi", ["Verdi", "Rossini", "Puccini"], "Antonio Vivaldi, prêtre et violoniste vénitien, a composé ces quatre concertos pour violon vers 1720."],
    ["Quel compositeur allemand a écrit les Concertos brandebourgeois ?", "Jean-Sébastien Bach", ["Haendel", "Telemann", "Mozart"], "Bach, grand maître de l'époque baroque, était aussi un organiste virtuose."],
    ["Quel compositeur russe a écrit la musique du ballet Casse-Noisette ?", "Tchaïkovski", ["Stravinsky", "Rachmaninov", "Moussorgski"], "Il a aussi composé Le Lac des cygnes et La Belle au bois dormant."],
    ["Quel compositeur français a écrit le Boléro en 1928 ?", "Maurice Ravel", ["Claude Debussy", "Erik Satie", "Camille Saint-Saëns"], "Le même thème y est répété en grossissant peu à peu, grâce à l'ajout des instruments."],
    ["Qui a composé Le Carnaval des animaux ?", "Camille Saint-Saëns", ["Maurice Ravel", "Georges Bizet", "Hector Berlioz"], "Chaque morceau imite un animal : le lion, les éléphants, le cygne, les poissons de l'aquarium…"],
    ["Qui a composé l'opéra Carmen ?", "Georges Bizet", ["Giuseppe Verdi", "Jacques Offenbach", "Charles Gounod"], "Créé en 1875 à Paris, Carmen est aujourd'hui l'un des opéras les plus joués au monde."],
    ["Quel compositeur russe a écrit le conte musical Pierre et le Loup ?", "Sergueï Prokofiev", ["Tchaïkovski", "Rimski-Korsakov", "Chostakovitch"], "Chaque personnage est joué par un instrument : l'oiseau par la flûte, le loup par les cors…"],
    ["Quel compositeur né en Pologne, installé à Paris, a surtout écrit pour le piano ?", "Frédéric Chopin", ["Franz Liszt", "Robert Schumann", "Claude Debussy"], "Ses nocturnes, valses et polonaises font de lui le grand poète du piano romantique."],
    ["Quel compositeur français a écrit Clair de lune et La Mer ?", "Claude Debussy", ["Maurice Ravel", "Gabriel Fauré", "Erik Satie"], "Sa musique, pleine de couleurs et d'atmosphères, est souvent rapprochée de l'impressionnisme."],
    ["Quel compositeur italien a écrit les opéras La Traviata et Aïda ?", "Giuseppe Verdi", ["Giacomo Puccini", "Gioachino Rossini", "Antonio Vivaldi"], "Verdi est devenu un symbole de l'unité italienne au XIXe siècle."],
    ["Quelle symphonie de Beethoven contient l'« Ode à la joie », devenue l'hymne européen ?", "La 9e symphonie", ["La 5e symphonie", "La 3e symphonie", "La 7e symphonie"], "Ce final chanté sur un poème de Schiller a été adopté comme hymne par le Conseil de l'Europe en 1972."],
    ["Quel compositeur dirige la musique à la cour de Louis XIV ?", "Jean-Baptiste Lully", ["Wolfgang Amadeus Mozart", "Jean-Philippe Rameau", "Hector Berlioz"], "Né à Florence, Lully a collaboré avec Molière, notamment pour Le Bourgeois gentilhomme."],
    ["Quel compositeur français a écrit la Symphonie fantastique en 1830 ?", "Hector Berlioz", ["Georges Bizet", "Claude Debussy", "Maurice Ravel"], "Cette œuvre raconte une histoire en musique : c'est une « symphonie à programme »."],
    ["Quel compositeur russe a fait scandale à Paris en 1913 avec Le Sacre du printemps ?", "Igor Stravinsky", ["Sergueï Prokofiev", "Piotr Ilitch Tchaïkovski", "Sergueï Rachmaninov"], "Ses rythmes brutaux et sa danse inhabituelle ont provoqué un chahut le soir de la création."],
    ["Quel trompettiste et chanteur de jazz américain a interprété What a Wonderful World ?", "Louis Armstrong", ["Miles Davis", "Duke Ellington", "Ray Charles"], "Surnommé « Satchmo », il est l'une des grandes figures du jazz né à La Nouvelle-Orléans."],
    ["De quelle époque musicale datent Vivaldi et Bach ?", "L'époque baroque", ["Le Moyen Âge", "L'époque romantique", "Le XXe siècle"], "La musique baroque s'étend environ de 1600 à 1750, date de la mort de Bach."],
    ["Quel compositeur autrichien est souvent surnommé le « père de la symphonie » ?", "Joseph Haydn", ["Wolfgang Amadeus Mozart", "Franz Schubert", "Gustav Mahler"], "Il a composé plus de cent symphonies et a été le professeur de Beethoven."],
  ]);

